// ELEMENTS:
// 1. Foto/vídeo em ecrã inteiro (src) com movimento de câmara lento (move: in|out|left|right|up)
// 2. Gradiente navy transparente no rodapé (só com legenda)
// 3. Barra azul IAD que se desenha
// 4. Eyebrow opcional (eyebrow) em branco, tracking largo
// 5. Legenda em serifa branca (anim.text)
// 6. Grão de filme + vinheta por cima de tudo
import React, { useId } from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY_RGB = "0,31,68";
const CYAN = "#DE212B";
const CORAL = "#DE212B";
const INK = "#001F44";
const WHITE = "#FFFFFF";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.26) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const PlanoPushIn: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const u = format === "landscape" ? H / 1080 : format === "half" ? (H / 960) * 0.85 : W / 1080;
  const T = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const src = String(p.src ?? "");
  const eyebrow = String(p.eyebrow ?? "").trim();
  const caption = String(anim.text ?? "").trim();

  // move: "in" (default) | "out" | "left" | "right" | "up" — vary it between scenes.
  const move = String(p.move ?? "in");
  const k = interpolate(f, [0, T], [0, 1], { ...clamp, easing: Easing.inOut(Easing.sin) });
  const camera =
    move === "out" ? `scale(${1.1 - 0.1 * k})`
    : move === "left" ? `scale(1.12) translateX(${3 - 6 * k}%)`
    : move === "right" ? `scale(1.12) translateX(${-3 + 6 * k}%)`
    : move === "up" ? `scale(1.12) translateY(${3 - 6 * k}%)`
    : `scale(${1 + 0.08 * k})`;
  const fadeIn = interpolate(f, [0, Math.round(0.4 * fps)], [0, 1], clamp);
  const rise = (delay: number): React.CSSProperties => {
    const t = interpolate(f, [Math.round(delay * fps), Math.round((delay + 0.7) * fps)], [0, 1], { ...clamp, easing: EASE });
    return { opacity: t, transform: `translateY(${(1 - t) * 24 * u}px)` };
  };
  const bar = interpolate(f, [Math.round(0.3 * fps), Math.round(0.9 * fps)], [0, 128 * u], { ...clamp, easing: EASE });

  return (
    <AbsoluteFill style={{ textShadow: "0 2px 18px rgba(0,0,0,0.45)", overflow: "hidden", backgroundColor: INK }}>
      <AbsoluteFill style={{ opacity: fadeIn, transform: camera }}>
        {src ? <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", filter: "saturate(0.88) contrast(1.05)" }} /> : null}
      </AbsoluteFill>
      {caption ? (
        <>
          <AbsoluteFill style={{ background: `linear-gradient(180deg, rgba(${NAVY_RGB},0) 52%, rgba(${NAVY_RGB},0.88) 100%)` }} />
          <div
            style={{
              position: "absolute",
              left: 72 * u,
              right: 72 * u,
              bottom: (format === "portrait" ? 184 : 72) * u,
              display: "flex",
              flexDirection: "column",
              gap: 24 * u,
            }}
          >
            <div style={{ display: "flex", alignItems: "center", gap: 28 * u }}>
              <div style={{ width: bar, height: 4 * u, background: CYAN }} />
              {eyebrow ? (
                <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 38 * u, letterSpacing: "0.22em", textTransform: "uppercase", color: WHITE, ...rise(0.4) }}>
                  {eyebrow}
                </div>
              ) : null}
            </div>
            <div style={{ fontFamily: FONTS.display, fontVariantNumeric: "lining-nums", fontWeight: 300, fontSize: 96 * u, lineHeight: 1.05, color: WHITE, ...rise(0.5) }}>{caption}</div>
          </div>
        </>
      ) : null}
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: "#DE212B" }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default PlanoPushIn;
